+              icon: Icons.settings_outlined,
+              label: 'Configurações',
+              onTap: () => _navigate(context, AppRoutePaths.configuracoes),
+            ),
+          ],
+        ),
+      ),
+    );
+  }
+
+  void _navigate(BuildContext context, String location) {
+    Navigator.of(context).pop();
+    context.go(location);
+  }
