117	/// re-run [_redirect] on every emission — go_router 18.1.1 exports no
118	/// `GoRouterRefreshStream` of its own (Code Map), so this is that small
119	/// local class.
120	class _GoRouterRefreshStream extends ChangeNotifier {
121	  _GoRouterRefreshStream(Stream<dynamic> stream) {
