        builder: (context, state) => AuthScreen(
          cubit: sl<AuthCubit>(),
          onAuthenticated: (context) => context.go(AppRoutePaths.home),
        ),
      ),
      GoRoute(
        path: AppRoutePaths.reauth,
        builder: (context, state) => const BiometricReauthPlaceholderScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.home,
        builder: (context, state) => const HomeChatPlaceholderScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.meusRegistros,
        builder: (context, state) => const MeusRegistrosPlaceholderScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.planosDeAcao,
        builder: (context, state) => const ActionPlansPlaceholderScreen(),
      ),
      GoRoute(
        path: AppRoutePaths.configuracoes,
        builder: (context, state) => const ConfiguracoesPlaceholderScreen(),
      ),
    ],
  );
}

/// I/O & Edge-Case Matrix:
/// - status not yet known (`null`) -> `/boot`, unless already there.
/// - `unauthenticated` -> `/auth`, unless already there.
/// - `authenticated`/`expired` -> leaves `/boot`/`/auth` for `/`; every
///   other location (including `/reauth`, reached only by the expiry
///   overlay's own explicit navigation) is left alone — a mid-session
///   expiry never navigates away (Story 1.5 behavior preserved), and the
///   three non-Home destinations stay reachable while `expired`.
///
/// AD-14 seam: Epic 2 (RF03) plugs a local `VaultStatus` gate in here,
/// checked *before* this session check (Cross-Story Dependencies: "vault
/// checked first") — e.g. `if (vaultStatus == VaultStatus.locked) return
/// AppRoutePaths.vaultLock;` ahead of the block below. Nothing here should
/// assume session validity alone ever decides access once that lands.
String? _redirect(SessionRepository sessionRepository, GoRouterState state) {
  final status = sessionRepository.currentStatus;
  final location = state.matchedLocation;

  if (status == null) {
    return location == AppRoutePaths.boot ? null : AppRoutePaths.boot;
  }

  if (status == SessionStatus.unauthenticated) {
    return location == AppRoutePaths.auth ? null : AppRoutePaths.auth;
  }

  // status is authenticated or expired.
  if (location == AppRoutePaths.boot || location == AppRoutePaths.auth) {
    return AppRoutePaths.home;
  }
  return null;
}

/// Wraps [stream] as a `Listenable` so `GoRouter`'s `refreshListenable` can
/// re-run [_redirect] on every emission — go_router 18.1.1 exports no
/// `GoRouterRefreshStream` of its own (Code Map), so this is that small
/// local class.
class _GoRouterRefreshStream extends ChangeNotifier {
  _GoRouterRefreshStream(Stream<dynamic> stream) {
    _subscription = stream.listen(
      (_) => notifyListeners(),
      // Mirrors `ExpiryOverlayHost`'s and `SessionRepositoryImpl`'s own
      // subscriptions to this same stream — no current implementation
      // ever errors on it, but a future one that did must not surface as
      // an unhandled zone exception here specifically.
      onError: (_, _) {},
    );
  }

  late final StreamSubscription<dynamic> _subscription;

  @override
  void dispose() {
    _subscription.cancel();
    super.dispose();
  }
}

import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:fpdart/fpdart.dart';

import '../../../../core/resource.dart';
import '../../domain/repositories/auth_repository.dart';
import '../../domain/repositories/session_repository.dart';
import '../../domain/validators/auth_validators.dart';
import 'auth_state.dart';

/// Drives Tela 0.1a. Calls [AuthRepository] directly (no use-case — Code Map:
/// this story's scope is small enough that an extra indirection layer isn't
/// justified yet); a BLoC/Cubit constructor never takes another BLoC/Cubit as
/// a dependency (architecture spine), so this takes the repository port.
///
/// Story 1.6 adds the [SessionRepository] dependency — presentation reaching
/// into its own feature's domain layer (AD-1), never a BLoC-to-BLoC
/// reference (AD-7) — so [submit]'s success branch can call
/// [SessionRepository.markAuthenticated] ahead of emitting its own success
/// state (see that method's doc for why the ordering matters).
class AuthCubit extends Cubit<AuthState> {
  AuthCubit(this._authRepository, this._sessionRepository)
    : super(const AuthState());

  final AuthRepository _authRepository;
  final SessionRepository _sessionRepository;

  /// Toggles login/signup — same screen, not a navigation (epics.md Story
  /// 1.3 AC). Keeps whatever the user already typed; clears any error from
  /// the previous mode's attempt. Goes through `copyWith` (rather than a raw
  /// `AuthState(...)`) so an in-flight `status` is never silently reset to
  /// idle by this call.
  void toggleMode() {
    emit(
      state.copyWith(
        mode: state.mode == AuthMode.login ? AuthMode.signUp : AuthMode.login,
        clearEmailError: true,
        clearPasswordError: true,
        clearFormError: true,
      ),
    );
  }

  void emailChanged(String value) {
    emit(
      state.copyWith(
        email: value,
        clearEmailError: true,
        clearPasswordError: true,
        clearFormError: true,
      ),
    );
  }

  void passwordChanged(String value) {
    emit(
      state.copyWith(
        password: value,
        clearEmailError: true,
        clearPasswordError: true,
        clearFormError: true,
      ),
    );
  }

  /// Validates locally first — a malformed email (or empty password) blocks
  /// submit *before* any round trip (epics.md Story 1.3 AC), each as its own
  /// single-field error so only the offending field is ever bordered. Only
  /// once local validation passes does it call `auth-signup`/`auth-login`
  /// with exactly `{email, password}` (the e-mail trimmed — stray
  /// leading/trailing whitespace must never reach the backend and risk a
  /// spurious `AUTH_INVALID`), saving the access token (via the repository)
  /// before this resolves.
  Future<void> submit() async {
    if (state.isSubmitting) {
      return;
    }

    final emailError = validateEmail(state.email);
    if (emailError != null) {
      emit(
        state.copyWith(
          emailError: emailError,
          clearPasswordError: true,
          clearFormError: true,
        ),
      );
      return;
    }

    final passwordError = validatePassword(state.password);
    if (passwordError != null) {
      emit(
        state.copyWith(
          passwordError: passwordError,
          clearEmailError: true,
          clearFormError: true,
        ),
      );
      return;
    }

    emit(
      state.copyWith(
        status: const ResourceLoading<Unit>(),
        clearEmailError: true,
        clearPasswordError: true,
        clearFormError: true,
      ),
    );

    final trimmedEmail = state.email.trim();
    final result = state.mode == AuthMode.login
        ? await _authRepository.logIn(
            email: trimmedEmail,
            password: state.password,
          )
        : await _authRepository.signUp(
            email: trimmedEmail,
            password: state.password,
          );

    result.match(
      (failure) => emit(
        state.copyWith(
          status: const ResourceIdle<Unit>(),
          formError: failure.message,
        ),
      ),
      // Clears the typed password once it's done its job — the access
      // token is already persisted by now, so there's no reason for the
      // plaintext value to keep sitting in this (DI-singleton, long-lived)
      // cubit's state after success. `markAuthenticated()` runs first
      // (Story 1.6 boundary) so the `go_router` redirect already sees
      // `authenticated` by the time this emission's `BlocListener` fires
      // `onAuthenticated`'s own navigation.
      (_) {
        _sessionRepository.markAuthenticated();
        emit(
          state.copyWith(status: const ResourceData<Unit>(unit), password: ''),
        );
      },
    );
  }
}

